// SPSC bounded ring over a SharedArrayBuffer; both ends run in workers
const ctl = new Int32Array(sab, 0, 2);               // [head, tail]
const data = new Int32Array(sab, 8, CAP);
function push(v) {                                   // producer agent
  const t = Atomics.load(ctl, 1);
  if (t - Atomics.load(ctl, 0) === CAP) return false;  // full: apply policy
  data[t % CAP] = v; Atomics.store(ctl, 1, t + 1);     // publish after payload
  Atomics.notify(ctl, 0); return true;
}
function pop() {                                     // consumer agent
  const h = Atomics.load(ctl, 0);
  if (h === Atomics.load(ctl, 1)) { Atomics.wait(ctl, 0, h); return null; }
  const v = data[h % CAP]; Atomics.store(ctl, 0, h + 1); return v;
}
